// The native converters inline four lookups that this file writes out at each use, as in the native code:
// the binary search of __CFToJISCharMap (1180 rows of a first unit and sixteen codes), of
// __CFFromJIS0208CharMap and __CFFromJIS0212CharMap (rows of a first code and 32 units), the user-defined
// area formula for U+E000 and above (row = (unit - 0xe000) / 188, code = unit + 0x44 * row + 0x1040, plus one
// when the column exceeds 0x3e, stored high byte first), and the bodies of JIS0208ToShiftJIS and
// ShiftJISToJIS0208. A search keeps the native order of its three comparisons; its midpoint is
// low + (high - low) / 2 in rows, as the emitted shift and exact-division multiply compute it.

// The {code, index} entries of macjapanese_to_uni_decomp: LDRH at offset 0, LDRB at offset 2, four bytes
// each. MacJapaneseDecompositionEntry is a descriptive name; the native type name is not in the evidence.
typedef struct {
    uint16_t code;
    uint8_t index;
} MacJapaneseDecompositionEntry;

// The sixteen-byte entries of __CFISO2022JPSequences: the sequence after ESC (LDR at offset 0), its length
// (LDRB at offset 8) and the mode it selects (LDRB at offset 9). ISO2022JPSequence is a descriptive name.
typedef struct {
    const char *sequence;
    uint8_t length;
    uint8_t mode;
} ISO2022JPSequence;

